-- Browse recon flow v1 (2026-10-08): detect-then-map-then-act-then-verify for unknown sites; strong CAPTCHA patterns stop the run alone while weak consent patterns stop it only in pairs, and every stop or miss fails with an honest code instead of acting blind.
-- Bounded generic-first finds (exact:false); the click chains straight off its find ref with no scroll between.

-- No public MCP tool/schema, protocol, primitive, VM, signing, auth, or transport boundary changes are introduced here.

select public.opera_register_workflow(
  'browse.recon',
  $wf${"steps":[{"id":"read0","type":"command","method":"page.read","params":{"tabId":{"$ref":"input.tabId"},"limit":12000}},{"name":"blocked","type":"set","value":false},{"name":"blockPattern","type":"set","value":""},{"name":"found","type":"set","value":false},{"id":"findRecaptcha","type":"command","method":"page.find","params":{"tabId":{"$ref":"input.tabId"},"text":"recaptcha","exact":false,"limit":5}},{"id":"chkRecaptcha","type":"if","condition":{"op":"truthy","left":{"$ref":"steps.findRecaptcha.result.count"}},"then":[{"name":"blocked","type":"set","value":true},{"name":"blockPattern","type":"set","value":"recaptcha"}],"else":[]},{"id":"findCaptcha","type":"command","method":"page.find","params":{"tabId":{"$ref":"input.tabId"},"text":"captcha","exact":false,"limit":5}},{"id":"chkCaptcha","type":"if","condition":{"op":"truthy","left":{"$ref":"steps.findCaptcha.result.count"}},"then":[{"name":"blocked","type":"set","value":true},{"name":"blockPattern","type":"set","value":"captcha"}],"else":[]},{"id":"findHuman","type":"command","method":"page.find","params":{"tabId":{"$ref":"input.tabId"},"text":"verify you are human","exact":false,"limit":5}},{"id":"chkHuman","type":"if","condition":{"op":"truthy","left":{"$ref":"steps.findHuman.result.count"}},"then":[{"name":"blocked","type":"set","value":true},{"name":"blockPattern","type":"set","value":"verify you are human"}],"else":[]},{"id":"findImages","type":"command","method":"page.find","params":{"tabId":{"$ref":"input.tabId"},"text":"select all images","exact":false,"limit":5}},{"id":"chkImages","type":"if","condition":{"op":"truthy","left":{"$ref":"steps.findImages.result.count"}},"then":[{"name":"blocked","type":"set","value":true},{"name":"blockPattern","type":"set","value":"select all images"}],"else":[]},{"id":"findConsent","type":"command","method":"page.find","params":{"tabId":{"$ref":"input.tabId"},"text":"consent","exact":false,"limit":5}},{"id":"findPrivacy","type":"command","method":"page.find","params":{"tabId":{"$ref":"input.tabId"},"text":"privacy notice","exact":false,"limit":5}},{"id":"chkWeak","type":"if","condition":{"op":"truthy","left":{"$ref":"steps.findConsent.result.count"}},"then":[{"id":"chkWeakBoth","type":"if","condition":{"op":"truthy","left":{"$ref":"steps.findPrivacy.result.count"}},"then":[{"name":"blocked","type":"set","value":true},{"name":"blockPattern","type":"set","value":"consent+privacy notice"}],"else":[]}],"else":[]},{"id":"gateBlocked","type":"if","condition":{"op":"truthy","left":{"$ref":"vars.blocked"}},"then":[{"type":"fail","code":"CAPTCHA_BLOCKED","message":"Blocked: CAPTCHA/human-verification stop rule matched; refusing to act. See blockPattern output for the matched pattern."}],"else":[]},{"id":"intent","type":"if","condition":{"op":"exists","left":{"$ref":"input.targetText"}},"then":[{"id":"findT","type":"command","method":"page.find","params":{"tabId":{"$ref":"input.tabId"},"text":{"$ref":"input.targetText"},"exact":false,"limit":10}},{"id":"hasTarget","type":"if","condition":{"op":"truthy","left":{"$ref":"steps.findT.result.count"}},"then":[{"name":"found","type":"set","value":true},{"name":"hit","type":"set","value":{"$ref":"steps.findT.result.item"}},{"id":"actPick","type":"if","condition":{"op":"eq","left":{"$ref":"input.action"},"right":"click"},"then":[{"id":"clickT","type":"command","method":"page.click","params":{"tabId":{"$ref":"input.tabId"},"ref":{"$ref":"steps.findT.result.item.ref"}}}],"else":[{"id":"fillT","type":"command","method":"page.fill","params":{"tabId":{"$ref":"input.tabId"},"ref":{"$ref":"steps.findT.result.item.ref"},"value":{"$ref":"input.value"}}}]},{"id":"read1","type":"command","method":"page.read","params":{"tabId":{"$ref":"input.tabId"},"limit":12000}},{"id":"expect","type":"if","condition":{"op":"exists","left":{"$ref":"input.expectText"}},"then":[{"id":"findV","type":"command","method":"page.find","params":{"tabId":{"$ref":"input.tabId"},"text":{"$ref":"input.expectText"},"exact":false,"limit":10}},{"id":"chkVerify","type":"if","condition":{"op":"falsey","left":{"$ref":"steps.findV.result.count"}},"then":[{"type":"fail","code":"VERIFY_FAILED","message":"Act ran but the expected text was not found afterwards."}],"else":[]}],"else":[]}],"else":[{"type":"fail","code":"TARGET_NOT_FOUND","message":"Target text was not found on the page."}]}],"else":[]}],"output":{"blocked":{"$ref":"vars.blocked"},"found":{"$ref":"vars.found"},"ref":{"$ref":"vars.hit.ref"},"label":{"$ref":"vars.hit.label"},"title":{"$ref":"steps.read0.result.page.title"},"url":{"$ref":"steps.read0.result.page.url"},"blockPattern":{"$ref":"vars.blockPattern"}}}$wf$,
  'Detect CAPTCHA and consent walls, map targets from read elements, act on a target, then verify the expectation on an unknown site.',
  true
);
